 1→/**
 2→ * @cipherbox/crypto - Type Definitions
 3→ *
 4→ * Core types for cryptographic operations.
 5→ */
 6→
 7→/**
 8→ * User's vault keypair for ECIES operations.
 9→ * Source agnostic - same type whether derived from Web3Auth or external wallet (ADR-001).
10→ */
11→export type VaultKey = {
12→  /** 65-byte uncompressed secp256k1 public key */
13→  publicKey: Uint8Array;
14→  /** 32-byte secp256k1 private key */
15→  privateKey: Uint8Array;
16→};
17→
18→/**
19→ * Result of AES-GCM encryption.
20→ * IV and ciphertext are kept separate for explicit handling.
21→ */
22→export type EncryptedData = {
23→  /** Encrypted data including authentication tag */
24→  ciphertext: Uint8Array;
25→  /** 12-byte initialization vector */
26→  iv: Uint8Array;
27→};
28→
29→/**
30→ * Error codes for categorized error handling.
31→ * Generic messages are still used externally to prevent oracle attacks.
32→ */
33→export type CryptoErrorCode =
34→  | 'ENCRYPTION_FAILED'
35→  | 'DECRYPTION_FAILED'
36→  | 'KEY_WRAPPING_FAILED'
37→  | 'KEY_UNWRAPPING_FAILED'
38→  | 'INVALID_KEY_SIZE'
39→  | 'INVALID_IV_SIZE'
40→  | 'INVALID_PUBLIC_KEY_SIZE'
41→  | 'INVALID_PUBLIC_KEY_FORMAT'
42→  | 'INVALID_PRIVATE_KEY_SIZE'
43→  | 'INVALID_INPUT'
44→  | 'INVALID_SIGNATURE_SIZE'
45→  | 'SIGNING_FAILED'
46→  | 'KEY_REWRAP_FAILED'
47→  | 'RANDOM_GENERATION_FAILED'
48→  | 'SECURE_CONTEXT_REQUIRED';
49→
50→/**
51→ * Custom error class for cryptographic operations.
52→ * Provides error codes for internal handling while keeping messages generic.
53→ */
54→export class CryptoError extends Error {
55→  readonly code: CryptoErrorCode;
56→
57→  constructor(message: string, code: CryptoErrorCode) {
58→    super(message);
59→    this.name = 'CryptoError';
60→    this.code = code;
61→
62→    // Maintain proper stack trace for V8 (Node.js-specific)
63→    const ErrorWithCapture = Error as typeof Error & {
64→      captureStackTrace?: (target: object, constructor: unknown) => void;
65→    };
66→    if (ErrorWithCapture.captureStackTrace) {
67→      ErrorWithCapture.captureStackTrace(this, CryptoError);
68→    }
69→  }
70→}
