 1→import { useAuthStore } from '../stores/auth.store';
 2→
 3→// Use VITE_API_URL if set, otherwise default to same-origin /api path for deployed environments
 4→const BASE_URL =
 5→  import.meta.env.VITE_API_URL ||
 6→  (typeof window !== 'undefined' ? `${window.location.origin}/api` : '/api');
 7→
 8→export const customInstance = async <T>(config: {
 9→  url: string;
10→  method: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
11→  params?: Record<string, string | number | boolean | undefined>;
12→  data?: unknown;
13→  headers?: Record<string, string>;
14→  signal?: AbortSignal;
15→  responseType?: 'json' | 'blob' | 'text';
16→}): Promise<T> => {
17→  const { url, method, params, data, headers, signal, responseType = 'json' } = config;
18→
19→  // Get auth token from store
20→  const accessToken = useAuthStore.getState().accessToken;
21→
22→  const queryString = params
23→    ? '?' +
24→      new URLSearchParams(
25→        Object.entries(params)
26→          .filter(([, v]) => v !== undefined)
27→          .map(([k, v]) => [k, String(v)])
28→      ).toString()
29→    : '';
30→
31→  const response = await fetch(`${BASE_URL}${url}${queryString}`, {
32→    method,
33→    headers: {
34→      // Only set Content-Type for JSON requests with body
35→      ...(data && responseType === 'json' ? { 'Content-Type': 'application/json' } : {}),
36→      ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}),
37→      ...headers,
38→    },
39→    body: data ? JSON.stringify(data) : undefined,
40→    signal,
41→  });
42→
43→  if (!response.ok) {
44→    const err = new Error(`HTTP error! status: ${response.status}`);
45→    (err as Error & { status: number }).status = response.status;
46→    throw err;
47→  }
48→
49→  // Return appropriate response type
50→  if (responseType === 'blob') {
51→    return response.blob() as Promise<T>;
52→  } else if (responseType === 'text') {
53→    return response.text() as Promise<T>;
54→  }
55→  // Responses with no body (204 No Content, 201 with void return, etc.)
56→  // Read as text first to avoid JSON parse error on empty bodies
57→  const text = await response.text();
58→  if (!text.trim()) {
59→    return undefined as T;
60→  }
61→  return JSON.parse(text);
62→};
63→
64→export default customInstance;
