  1→/**
  2→ * @cipherbox/crypto - Folder Metadata Encryption
  3→ *
  4→ * Encrypts and decrypts folder metadata using AES-256-GCM.
  5→ * Folder metadata is JSON serialized before encryption.
  6→ */
  7→
  8→import { encryptAesGcm, decryptAesGcm } from '../aes';
  9→import { generateIv, bytesToHex, hexToBytes } from '../utils';
 10→import { CryptoError } from '../types';
 11→import { ECIES_MIN_CIPHERTEXT_SIZE } from '../constants';
 12→import type { FolderMetadata, EncryptedFolderMetadata } from './types';
 13→
 14→/**
 15→ * [SECURITY: MEDIUM-08] Chunk-based base64 encoding to avoid call stack issues
 16→ * with large Uint8Arrays (spread operator has argument limits ~65536)
 17→ */
 18→function uint8ArrayToBase64(bytes: Uint8Array): string {
 19→  const CHUNK_SIZE = 32768;
 20→  let result = '';
 21→  for (let i = 0; i < bytes.length; i += CHUNK_SIZE) {
 22→    const chunk = bytes.subarray(i, Math.min(i + CHUNK_SIZE, bytes.length));
 23→    result += String.fromCharCode(...chunk);
 24→  }
 25→  return btoa(result);
 26→}
 27→
 28→/**
 29→ * [SECURITY: MEDIUM-07] Runtime validation for decrypted folder metadata.
 30→ * Accepts only v2 schema. Rejects v1 data.
 31→ * - v2 children: FolderEntry | FilePointer (with fileMetaIpnsName field)
 32→ */
 33→export function validateFolderMetadata(data: unknown): FolderMetadata {
 34→  if (typeof data !== 'object' || data === null) {
 35→    throw new CryptoError('Invalid metadata format: not an object', 'DECRYPTION_FAILED');
 36→  }
 37→
 38→  const obj = data as Record<string, unknown>;
 39→
 40→  // Only v2 is accepted
 41→  if (obj.version !== 'v2') {
 42→    throw new CryptoError(
 43→      'Invalid metadata format: unsupported version (only v2 accepted)',
 44→      'DECRYPTION_FAILED'
 45→    );
 46→  }
 47→
 48→  // Validate children array
 49→  if (!Array.isArray(obj.children)) {
 50→    throw new CryptoError('Invalid metadata format: children must be array', 'DECRYPTION_FAILED');
 51→  }
 52→
 53→  // Basic validation of each child entry
 54→  for (const child of obj.children) {
 55→    if (typeof child !== 'object' || child === null) {
 56→      throw new CryptoError('Invalid metadata format: invalid child entry', 'DECRYPTION_FAILED');
 57→    }
 58→    const entry = child as Record<string, unknown>;
 59→    if (entry.type !== 'file' && entry.type !== 'folder') {
 60→      throw new CryptoError('Invalid metadata format: unknown child type', 'DECRYPTION_FAILED');
 61→    }
 62→    if (typeof entry.id !== 'string' || typeof entry.name !== 'string') {
 63→      throw new CryptoError('Invalid metadata format: missing id or name', 'DECRYPTION_FAILED');
 64→    }
 65→
 66→    // v2 file children must have fileMetaIpnsName (FilePointer)
 67→    if (entry.type === 'file') {
 68→      const hasIpnsName = typeof entry.fileMetaIpnsName === 'string';
 69→      if (!hasIpnsName) {
 70→        throw new CryptoError(
 71→          'Invalid metadata format: file entry must have fileMetaIpnsName',
 72→          'DECRYPTION_FAILED'
 73→        );
 74→      }
 75→      // Optional: ipnsPrivateKeyEncrypted must be a hex string long enough to hold ECIES output
 76→      if (entry.ipnsPrivateKeyEncrypted !== undefined) {
 77→        if (
 78→          typeof entry.ipnsPrivateKeyEncrypted !== 'string' ||
 79→          entry.ipnsPrivateKeyEncrypted.length < ECIES_MIN_CIPHERTEXT_SIZE * 2
 80→        ) {
 81→          throw new CryptoError(
 82→            `Invalid metadata format: ipnsPrivateKeyEncrypted must be a hex string (min ${ECIES_MIN_CIPHERTEXT_SIZE * 2} chars)`,
 83→            'DECRYPTION_FAILED'
 84→          );
 85→        }
 86→      }
 87→    }
 88→  }
 89→
 90→  return data as FolderMetadata;
 91→}
 92→
 93→/**
 94→ * Encrypts folder metadata with AES-256-GCM.
 95→ *
 96→ * @param metadata - Plaintext folder metadata object (v2)
 97→ * @param folderKey - 32-byte AES key for this folder
 98→ * @returns Encrypted metadata with IV (hex) and ciphertext (base64)
 99→ */
100→export async function encryptFolderMetadata(
101→  metadata: FolderMetadata,
102→  folderKey: Uint8Array
103→): Promise<EncryptedFolderMetadata> {
104→  // Generate random IV for this encryption
105→  const iv = generateIv();
106→
107→  // Serialize metadata to JSON bytes
108→  const plaintext = new TextEncoder().encode(JSON.stringify(metadata));
109→
110→  // Encrypt with AES-256-GCM
111→  const ciphertext = await encryptAesGcm(plaintext, folderKey, iv);
112→
113→  // Encode for storage
114→  // [SECURITY: MEDIUM-08] Use chunked base64 encoding for large metadata
115→  return {
116→    iv: bytesToHex(iv),
117→    data: uint8ArrayToBase64(ciphertext),
118→  };
119→}
120→
121→/**
122→ * Decrypts folder metadata encrypted with AES-256-GCM.
123→ * Returns v2 metadata only. Rejects v1 data.
124→ *
125→ * @param encrypted - Encrypted metadata with IV (hex) and ciphertext (base64)
126→ * @param folderKey - 32-byte AES key for this folder
127→ * @returns Decrypted folder metadata object (v2)
128→ * @throws CryptoError if decryption fails (wrong key, corrupted data, etc.)
129→ */
130→export async function decryptFolderMetadata(
131→  encrypted: EncryptedFolderMetadata,
132→  folderKey: Uint8Array
133→): Promise<FolderMetadata> {
134→  // Decode IV and ciphertext
135→  const iv = hexToBytes(encrypted.iv);
136→  const ciphertext = Uint8Array.from(atob(encrypted.data), (c) => c.charCodeAt(0));
137→
138→  // Decrypt with AES-256-GCM
139→  const plaintext = await decryptAesGcm(ciphertext, folderKey, iv);
140→
141→  // Parse JSON back to metadata object
142→  // [SECURITY: MEDIUM-07] Validate the decrypted data before returning
143→  const parsed = JSON.parse(new TextDecoder().decode(plaintext));
144→  return validateFolderMetadata(parsed);
145→}
146→

 1→/**
 2→ * @cipherbox/crypto - Folder Metadata Types
 3→ *
 4→ * Type definitions for encrypted folder metadata stored in IPNS records.
 5→ * v2 schema with per-file IPNS pointers (FilePointer children).
 6→ */
 7→
 8→import type { FilePointer } from '../file/types';
 9→
10→/**
11→ * Decrypted folder metadata structure (v2).
12→ * The entire FolderMetadata object is encrypted as a single blob with AES-256-GCM.
13→ * Children are FolderEntry (subfolders) or FilePointer (slim IPNS references).
14→ */
15→export type FolderMetadata = {
16→  /** Schema version */
17→  version: 'v2';
18→  /** Folders and file pointers in this folder */
19→  children: FolderChild[];
20→};
21→
22→/**
23→ * A child entry can be either a folder or a file pointer.
24→ */
25→export type FolderChild = FolderEntry | FilePointer;
26→
27→/**
28→ * Subfolder entry within folder metadata.
29→ * Contains ECIES-wrapped keys for accessing the subfolder.
30→ */
31→export type FolderEntry = {
32→  type: 'folder';
33→  /** UUID for internal reference */
34→  id: string;
35→  /** Folder name (plaintext, since whole metadata is encrypted) */
36→  name: string;
37→  /** IPNS name for this subfolder (k51... format) */
38→  ipnsName: string;
39→  /** Hex-encoded ECIES-wrapped Ed25519 private key for IPNS signing */
40→  ipnsPrivateKeyEncrypted: string;
41→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting subfolder metadata */
42→  folderKeyEncrypted: string;
43→  /** Creation timestamp (Unix ms) */
44→  createdAt: number;
45→  /** Last modification timestamp (Unix ms) */
46→  modifiedAt: number;
47→};
48→
49→/**
50→ * Encrypted folder metadata for storage/transmission.
51→ * This is what gets uploaded to IPFS and referenced by IPNS.
52→ */
53→export type EncryptedFolderMetadata = {
54→  /** Hex-encoded 12-byte IV for AES-GCM */
55→  iv: string;
56→  /** Base64-encoded AES-GCM ciphertext (includes 16-byte auth tag) */
57→  data: string;
58→};
59→

  1→/**
  2→ * @cipherbox/crypto - File Metadata Encryption
  3→ *
  4→ * Encrypts and decrypts per-file metadata using AES-256-GCM.
  5→ * File metadata is encrypted with the parent folder's folderKey
  6→ * (NOT the file's own encryption key).
  7→ */
  8→
  9→import { encryptAesGcm, decryptAesGcm } from '../aes';
 10→import { generateIv, bytesToHex, hexToBytes } from '../utils';
 11→import { CryptoError } from '../types';
 12→import type { FileMetadata, EncryptedFileMetadata, VersionEntry } from './types';
 13→
 14→/**
 15→ * [SECURITY: MEDIUM-08] Chunk-based base64 encoding to avoid call stack issues
 16→ * with large Uint8Arrays (spread operator has argument limits ~65536)
 17→ */
 18→function uint8ArrayToBase64(bytes: Uint8Array): string {
 19→  const CHUNK_SIZE = 32768;
 20→  let result = '';
 21→  for (let i = 0; i < bytes.length; i += CHUNK_SIZE) {
 22→    const chunk = bytes.subarray(i, Math.min(i + CHUNK_SIZE, bytes.length));
 23→    result += String.fromCharCode(...chunk);
 24→  }
 25→  return btoa(result);
 26→}
 27→
 28→/**
 29→ * Validates a single version entry from the versions array.
 30→ * All fields are required (versions always have explicit encryption mode).
 31→ */
 32→function validateVersionEntry(entry: unknown, index: number): VersionEntry {
 33→  if (typeof entry !== 'object' || entry === null) {
 34→    throw new CryptoError(
 35→      `Invalid file metadata format: versions[${index}] is not an object`,
 36→      'DECRYPTION_FAILED'
 37→    );
 38→  }
 39→
 40→  const obj = entry as Record<string, unknown>;
 41→
 42→  if (typeof obj.cid !== 'string') {
 43→    throw new CryptoError(
 44→      `Invalid file metadata format: versions[${index}].cid must be string`,
 45→      'DECRYPTION_FAILED'
 46→    );
 47→  }
 48→  if (typeof obj.fileKeyEncrypted !== 'string') {
 49→    throw new CryptoError(
 50→      `Invalid file metadata format: versions[${index}].fileKeyEncrypted must be string`,
 51→      'DECRYPTION_FAILED'
 52→    );
 53→  }
 54→  if (typeof obj.fileIv !== 'string') {
 55→    throw new CryptoError(
 56→      `Invalid file metadata format: versions[${index}].fileIv must be string`,
 57→      'DECRYPTION_FAILED'
 58→    );
 59→  }
 60→  if (typeof obj.size !== 'number') {
 61→    throw new CryptoError(
 62→      `Invalid file metadata format: versions[${index}].size must be number`,
 63→      'DECRYPTION_FAILED'
 64→    );
 65→  }
 66→  if (typeof obj.timestamp !== 'number') {
 67→    throw new CryptoError(
 68→      `Invalid file metadata format: versions[${index}].timestamp must be number`,
 69→      'DECRYPTION_FAILED'
 70→    );
 71→  }
 72→  if (obj.encryptionMode !== 'GCM' && obj.encryptionMode !== 'CTR') {
 73→    throw new CryptoError(
 74→      `Invalid file metadata format: versions[${index}].encryptionMode must be GCM or CTR`,
 75→      'DECRYPTION_FAILED'
 76→    );
 77→  }
 78→
 79→  return {
 80→    cid: obj.cid as string,
 81→    fileKeyEncrypted: obj.fileKeyEncrypted as string,
 82→    fileIv: obj.fileIv as string,
 83→    size: obj.size as number,
 84→    timestamp: obj.timestamp as number,
 85→    encryptionMode: obj.encryptionMode as 'GCM' | 'CTR',
 86→  };
 87→}
 88→
 89→/**
 90→ * [SECURITY: MEDIUM-07] Runtime validation for decrypted file metadata.
 91→ * Ensures the decrypted data conforms to the expected FileMetadata schema.
 92→ */
 93→export function validateFileMetadata(data: unknown): FileMetadata {
 94→  if (typeof data !== 'object' || data === null) {
 95→    throw new CryptoError('Invalid file metadata format: not an object', 'DECRYPTION_FAILED');
 96→  }
 97→
 98→  const obj = data as Record<string, unknown>;
 99→
100→  // Validate version field
101→  if (obj.version !== 'v1') {
102→    throw new CryptoError('Invalid file metadata format: unsupported version', 'DECRYPTION_FAILED');
103→  }
104→
105→  // Validate required string fields
106→  if (typeof obj.cid !== 'string') {
107→    throw new CryptoError('Invalid file metadata format: cid must be string', 'DECRYPTION_FAILED');
108→  }
109→  if (typeof obj.fileKeyEncrypted !== 'string') {
110→    throw new CryptoError(
111→      'Invalid file metadata format: fileKeyEncrypted must be string',
112→      'DECRYPTION_FAILED'
113→    );
114→  }
115→  if (typeof obj.fileIv !== 'string') {
116→    throw new CryptoError(
117→      'Invalid file metadata format: fileIv must be string',
118→      'DECRYPTION_FAILED'
119→    );
120→  }
121→  if (typeof obj.mimeType !== 'string') {
122→    throw new CryptoError(
123→      'Invalid file metadata format: mimeType must be string',
124→      'DECRYPTION_FAILED'
125→    );
126→  }
127→
128→  // Validate required number fields
129→  if (typeof obj.size !== 'number') {
130→    throw new CryptoError('Invalid file metadata format: size must be number', 'DECRYPTION_FAILED');
131→  }
132→  if (typeof obj.createdAt !== 'number') {
133→    throw new CryptoError(
134→      'Invalid file metadata format: createdAt must be number',
135→      'DECRYPTION_FAILED'
136→    );
137→  }
138→  if (typeof obj.modifiedAt !== 'number') {
139→    throw new CryptoError(
140→      'Invalid file metadata format: modifiedAt must be number',
141→      'DECRYPTION_FAILED'
142→    );
143→  }
144→
145→  // Validate optional encryptionMode: if present must be 'GCM' or 'CTR'; if absent default to 'GCM'
146→  if (obj.encryptionMode !== undefined) {
147→    if (obj.encryptionMode !== 'GCM' && obj.encryptionMode !== 'CTR') {
148→      throw new CryptoError(
149→        'Invalid file metadata format: encryptionMode must be GCM or CTR',
150→        'DECRYPTION_FAILED'
151→      );
152→    }
153→  }
154→
155→  // Validate optional versions array
156→  let validatedVersions: VersionEntry[] | undefined;
157→  if (obj.versions !== undefined) {
158→    if (!Array.isArray(obj.versions)) {
159→      throw new CryptoError(
160→        'Invalid file metadata format: versions must be an array',
161→        'DECRYPTION_FAILED'
162→      );
163→    }
164→    if (obj.versions.length > 0) {
165→      validatedVersions = obj.versions.map((entry: unknown, i: number) =>
166→        validateVersionEntry(entry, i)
167→      );
168→    }
169→  }
170→
171→  const result: FileMetadata = {
172→    version: 'v1',
173→    cid: obj.cid as string,
174→    fileKeyEncrypted: obj.fileKeyEncrypted as string,
175→    fileIv: obj.fileIv as string,
176→    size: obj.size as number,
177→    mimeType: obj.mimeType as string,
178→    encryptionMode: (obj.encryptionMode as 'GCM' | 'CTR' | undefined) ?? 'GCM',
179→    createdAt: obj.createdAt as number,
180→    modifiedAt: obj.modifiedAt as number,
181→  };
182→
183→  if (validatedVersions) {
184→    result.versions = validatedVersions;
185→  }
186→
187→  return result;
188→}
189→
190→/**
191→ * Encrypts file metadata with AES-256-GCM using the parent folder's key.
192→ *
193→ * @param metadata - Plaintext file metadata object
194→ * @param folderKey - 32-byte AES key of the parent folder
195→ * @returns Encrypted metadata with IV (hex) and ciphertext (base64)
196→ */
197→export async function encryptFileMetadata(
198→  metadata: FileMetadata,
199→  folderKey: Uint8Array
200→): Promise<EncryptedFileMetadata> {
201→  // Generate random IV for this encryption
202→  const iv = generateIv();
203→
204→  // Serialize metadata to JSON bytes
205→  const plaintext = new TextEncoder().encode(JSON.stringify(metadata));
206→
207→  // Encrypt with AES-256-GCM
208→  const ciphertext = await encryptAesGcm(plaintext, folderKey, iv);
209→
210→  // Encode for storage
211→  // [SECURITY: MEDIUM-08] Use chunked base64 encoding for large metadata
212→  return {
213→    iv: bytesToHex(iv),
214→    data: uint8ArrayToBase64(ciphertext),
215→  };
216→}
217→
218→/**
219→ * Decrypts file metadata encrypted with AES-256-GCM.
220→ *
221→ * @param encrypted - Encrypted metadata with IV (hex) and ciphertext (base64)
222→ * @param folderKey - 32-byte AES key of the parent folder
223→ * @returns Decrypted file metadata object
224→ * @throws CryptoError if decryption fails (wrong key, corrupted data, etc.)
225→ */
226→export async function decryptFileMetadata(
227→  encrypted: EncryptedFileMetadata,
228→  folderKey: Uint8Array
229→): Promise<FileMetadata> {
230→  // Decode IV and ciphertext
231→  const iv = hexToBytes(encrypted.iv);
232→  const ciphertext = Uint8Array.from(atob(encrypted.data), (c) => c.charCodeAt(0));
233→
234→  // Decrypt with AES-256-GCM
235→  const plaintext = await decryptAesGcm(ciphertext, folderKey, iv);
236→
237→  // Parse JSON back to metadata object
238→  // [SECURITY: MEDIUM-07] Validate the decrypted data before returning
239→  let parsed: unknown;
240→  try {
241→    parsed = JSON.parse(new TextDecoder().decode(plaintext));
242→  } catch {
243→    throw new CryptoError('Invalid file metadata format: not valid JSON', 'DECRYPTION_FAILED');
244→  }
245→  return validateFileMetadata(parsed);
246→}
