 1→/**
 2→ * @cipherbox/crypto - Per-File Metadata Types
 3→ *
 4→ * Type definitions for per-file IPNS metadata records.
 5→ * Each file gets its own IPNS record containing encrypted metadata,
 6→ * while the parent folder only stores a slim FilePointer reference.
 7→ */
 8→
 9→/** A single past version of a file. Stores full crypto context for independent decryption. */
10→export type VersionEntry = {
11→  /** IPFS CID of the encrypted file content for this version */
12→  cid: string;
13→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting this version */
14→  fileKeyEncrypted: string;
15→  /** Hex-encoded IV used for this version's encryption */
16→  fileIv: string;
17→  /** Original file size in bytes (before encryption) */
18→  size: number;
19→  /** When this version was created (Unix ms) -- i.e., when it became a "past" version */
20→  timestamp: number;
21→  /** Encryption mode used for this version */
22→  encryptionMode: 'GCM' | 'CTR';
23→};
24→
25→/**
26→ * Decrypted per-file metadata structure.
27→ * Stored as an encrypted blob in the file's own IPNS record.
28→ * Encrypted with the parent folder's folderKey (NOT the file's own key).
29→ */
30→export type FileMetadata = {
31→  /** Schema version */
32→  version: 'v1';
33→  /** IPFS CID of the encrypted file content */
34→  cid: string;
35→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting file */
36→  fileKeyEncrypted: string;
37→  /** Hex-encoded IV used for file encryption */
38→  fileIv: string;
39→  /** Original file size in bytes (before encryption) */
40→  size: number;
41→  /** MIME type of the original file */
42→  mimeType: string;
43→  /** Encryption mode (optional for backward compat; defaults to 'GCM') */
44→  encryptionMode?: 'GCM' | 'CTR';
45→  /** Creation timestamp (Unix ms) */
46→  createdAt: number;
47→  /** Last modification timestamp (Unix ms) */
48→  modifiedAt: number;
49→  /** Past versions of this file (newest first). Omitted if no versions exist. */
50→  versions?: VersionEntry[];
51→};
52→
53→/**
54→ * Slim file reference stored in v2 folder metadata.
55→ * Points to a file's own IPNS record instead of embedding all file data inline.
56→ */
57→export type FilePointer = {
58→  type: 'file';
59→  /** UUID for internal reference */
60→  id: string;
61→  /** File name (plaintext, since folder metadata is encrypted) */
62→  name: string;
63→  /** IPNS name of the file's own metadata record */
64→  fileMetaIpnsName: string;
65→  /** Hex-encoded ECIES-wrapped Ed25519 private key for signing this file's IPNS record.
66→   *  Present for files created after the random-key migration. Absent for legacy files
67→   *  whose IPNS key is derived deterministically via HKDF. */
68→  ipnsPrivateKeyEncrypted?: string;
69→  /** Creation timestamp (Unix ms) */
70→  createdAt: number;
71→  /** Last modification timestamp (Unix ms) */
72→  modifiedAt: number;
73→};
74→
75→/**
76→ * Encrypted file metadata for storage/transmission.
77→ * Same format as EncryptedFolderMetadata (hex IV + base64 ciphertext).
78→ */
79→export type EncryptedFileMetadata = {
80→  /** Hex-encoded 12-byte IV for AES-GCM */
81→  iv: string;
82→  /** Base64-encoded AES-GCM ciphertext (includes 16-byte auth tag) */
83→  data: string;
84→};
85→

  1→/**
  2→ * @cipherbox/crypto - File IPNS Key Management
  3→ *
  4→ * Two strategies for per-file IPNS keypairs:
  5→ *
  6→ * 1. Deterministic (legacy): `deriveFileIpnsKeypair` derives an Ed25519 keypair
  7→ *    from the user's secp256k1 privateKey + fileId via HKDF-SHA256. Used for
  8→ *    files created before random key migration.
  9→ *
 10→ * 2. Random (new files): `generateFileIpnsKeypair` generates a fresh Ed25519
 11→ *    keypair via CSPRNG. The private key is ECIES-wrapped and stored in the
 12→ *    parent folder's FilePointer so it can be recovered from any device.
 13→ *
 14→ * Deterministic derivation path:
 15→ *   secp256k1 privateKey (32 bytes)
 16→ *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-file-ipns-v1:{fileId}")
 17→ *     -> 32-byte Ed25519 seed
 18→ *     -> Ed25519 keypair
 19→ *     -> IPNS name (k51...)
 20→ *
 21→ * Domain separation: The fileId in the HKDF info string ensures each file
 22→ * gets a unique IPNS keypair. Different from vault ("cipherbox-vault-ipns-v1")
 23→ * and registry ("cipherbox-device-registry-ipns-v1") derivation domains.
 24→ */
 25→
 26→import { deriveKey } from '../keys/derive';
 27→import * as ed from '@noble/ed25519';
 28→import { deriveIpnsName } from '../ipns/derive-name';
 29→import { generateEd25519Keypair } from '../ed25519/keygen';
 30→import { CryptoError } from '../types';
 31→import { SECP256K1_PRIVATE_KEY_SIZE } from '../constants';
 32→
 33→const FILE_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
 34→
 35→/**
 36→ * Derive a deterministic Ed25519 IPNS keypair for a specific file.
 37→ *
 38→ * Given the same secp256k1 privateKey and fileId, this always produces
 39→ * the same IPNS name, enabling file metadata discovery from any device.
 40→ *
 41→ * @param userPrivateKey - 32-byte secp256k1 private key
 42→ * @param fileId - Unique file identifier (UUID, minimum 10 characters)
 43→ * @returns Ed25519 keypair and IPNS name for the file's metadata record
 44→ * @throws CryptoError if the private key is not 32 bytes or fileId is invalid
 45→ */
 46→export async function deriveFileIpnsKeypair(
 47→  userPrivateKey: Uint8Array,
 48→  fileId: string
 49→): Promise<{
 50→  privateKey: Uint8Array;
 51→  publicKey: Uint8Array;
 52→  ipnsName: string;
 53→}> {
 54→  // Validate input key length
 55→  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
 56→    throw new CryptoError('Invalid private key size for file IPNS derivation', 'INVALID_KEY_SIZE');
 57→  }
 58→
 59→  // Validate fileId
 60→  if (!fileId || fileId.length < 10) {
 61→    throw new CryptoError(
 62→      'Invalid fileId: must be a non-empty string of at least 10 characters',
 63→      'INVALID_INPUT'
 64→    );
 65→  }
 66→
 67→  // HKDF info includes fileId for per-file domain separation
 68→  const fileHkdfInfo = new TextEncoder().encode(`cipherbox-file-ipns-v1:${fileId}`);
 69→
 70→  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
 71→  const ed25519Seed = await deriveKey({
 72→    inputKey: userPrivateKey,
 73→    salt: FILE_HKDF_SALT,
 74→    info: fileHkdfInfo,
 75→    outputLength: 32,
 76→  });
 77→
 78→  // 2. Derive Ed25519 public key from seed (deterministic)
 79→  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
 80→
 81→  // 3. Derive IPNS name from Ed25519 public key (k51... format)
 82→  const ipnsName = await deriveIpnsName(ed25519PublicKey);
 83→
 84→  return {
 85→    privateKey: ed25519Seed,
 86→    publicKey: ed25519PublicKey,
 87→    ipnsName,
 88→  };
 89→}
 90→
 91→/**
 92→ * Generate a random Ed25519 IPNS keypair for a new file.
 93→ *
 94→ * Unlike `deriveFileIpnsKeypair`, this produces a non-deterministic keypair.
 95→ * The private key must be ECIES-wrapped and stored in the FilePointer so it
 96→ * can be recovered from folder metadata.
 97→ *
 98→ * @returns Ed25519 keypair and IPNS name for the file's metadata record
 99→ */
100→export async function generateFileIpnsKeypair(): Promise<{
101→  privateKey: Uint8Array;
102→  publicKey: Uint8Array;
103→  ipnsName: string;
104→}> {
105→  const keypair = generateEd25519Keypair();
106→  const ipnsName = await deriveIpnsName(keypair.publicKey);
107→
108→  return {
109→    privateKey: keypair.privateKey,
110→    publicKey: keypair.publicKey,
111→    ipnsName,
112→  };
113→}
114→

 1→/**
 2→ * @cipherbox/crypto - Device Registry Types
 3→ *
 4→ * Type definitions for the encrypted device registry stored on IPFS/IPNS.
 5→ * The registry tracks authenticated devices with rich metadata and supports
 6→ * cross-device approval (Phase 12.4).
 7→ */
 8→
 9→/** Authorization status for a device in the registry */
10→export type DeviceAuthStatus = 'pending' | 'authorized' | 'revoked';
11→
12→/** Platform identifier for a device */
13→export type DevicePlatform = 'web' | 'macos' | 'linux' | 'windows';
14→
15→/**
16→ * Individual device entry in the registry.
17→ *
18→ * Each entry represents a physical device that has authenticated
19→ * with the user's CipherBox account.
20→ */
21→export type DeviceEntry = {
22→  /** SHA-256 hash of device's Ed25519 public key (hex) */
23→  deviceId: string;
24→  /** Device's Ed25519 public key (hex) - for future key exchange in Phase 12.4 */
25→  publicKey: string;
26→  /** Human-readable device name (e.g., "Chrome on macOS") */
27→  name: string;
28→  /** Platform identifier */
29→  platform: DevicePlatform;
30→  /** App version string (e.g., "0.2.0") */
31→  appVersion: string;
32→  /** Device model or OS version (e.g., "macOS 15.2", "Chrome 123") */
33→  deviceModel: string;
34→  /** SHA-256 hash of IP address at registration (hex, privacy-preserving) */
35→  ipHash: string;
36→  /** Authorization status */
37→  status: DeviceAuthStatus;
38→  /** When device was first registered (Unix ms) */
39→  createdAt: number;
40→  /** Last time device synced with registry (Unix ms) */
41→  lastSeenAt: number;
42→  /** When device was revoked (Unix ms, null if not revoked) */
43→  revokedAt: number | null;
44→  /** Device ID of the device that performed revocation (null if not revoked) */
45→  revokedBy: string | null;
46→};
47→
48→/**
49→ * The full device registry.
50→ *
51→ * Encrypted as a single JSON blob with the user's publicKey via ECIES,
52→ * then stored on IPFS and referenced by a dedicated IPNS name.
53→ */
54→export type DeviceRegistry = {
55→  /** Schema version for future migrations */
56→  version: 'v1';
57→  /** Monotonically increasing update counter */
58→  sequenceNumber: number;
59→  /** Array of all device entries (including revoked, for audit trail) */
60→  devices: DeviceEntry[];
61→};
