 1→/**
 2→ * @cipherbox/crypto - Device Registry Encryption
 3→ *
 4→ * ECIES encryption/decryption for the device registry blob.
 5→ * Uses the same wrapKey/unwrapKey primitives as folder key wrapping.
 6→ *
 7→ * Note: wrapKey/unwrapKey handle arbitrary-length data (not just 32-byte keys).
 8→ * eciesjs internally uses AES-256-GCM for the symmetric portion, so any
 9→ * length payload works. Overhead is ~97 bytes (65 ephemeral pubkey + 16 nonce + 16 tag).
10→ * A 10KB registry produces ~10.1KB ciphertext.
11→ */
12→
13→import { wrapKey } from '../ecies/encrypt';
14→import { unwrapKey } from '../ecies/decrypt';
15→import { validateDeviceRegistry } from './schema';
16→import { CryptoError } from '../types';
17→import { clearBytes } from '../utils/memory';
18→import type { DeviceRegistry } from './types';
19→
20→/**
21→ * Encrypt the device registry for IPFS storage.
22→ *
23→ * Serializes the registry to JSON and encrypts with ECIES using
24→ * the user's secp256k1 publicKey. Only the holder of the corresponding
25→ * privateKey can decrypt it.
26→ *
27→ * @param registry - The device registry to encrypt
28→ * @param userPublicKey - 65-byte uncompressed secp256k1 public key
29→ * @returns Encrypted registry blob
30→ */
31→export async function encryptRegistry(
32→  registry: DeviceRegistry,
33→  userPublicKey: Uint8Array
34→): Promise<Uint8Array> {
35→  const plaintext = new TextEncoder().encode(JSON.stringify(registry));
36→  try {
37→    return await wrapKey(plaintext, userPublicKey);
38→  } finally {
39→    clearBytes(plaintext);
40→  }
41→}
42→
43→/**
44→ * Decrypt the device registry from IPFS storage.
45→ *
46→ * Decrypts with ECIES using the user's secp256k1 privateKey,
47→ * parses the JSON, and validates the schema.
48→ *
49→ * @param encrypted - ECIES-encrypted registry blob from IPFS
50→ * @param userPrivateKey - 32-byte secp256k1 private key
51→ * @returns Validated DeviceRegistry
52→ * @throws CryptoError if decryption or validation fails
53→ */
54→export async function decryptRegistry(
55→  encrypted: Uint8Array,
56→  userPrivateKey: Uint8Array
57→): Promise<DeviceRegistry> {
58→  const plaintext = await unwrapKey(encrypted, userPrivateKey);
59→  try {
60→    const json = new TextDecoder().decode(plaintext);
61→    const parsed = JSON.parse(json);
62→    return validateDeviceRegistry(parsed);
63→  } catch (error) {
64→    if (error instanceof CryptoError) throw error;
65→    throw new CryptoError('Registry decryption produced invalid data', 'DECRYPTION_FAILED');
66→  } finally {
67→    clearBytes(plaintext);
68→  }
69→}
70→

 1→/**
 2→ * @cipherbox/crypto - Registry IPNS Key Derivation
 3→ *
 4→ * Derives a deterministic Ed25519 IPNS keypair for the device registry
 5→ * from the user's secp256k1 privateKey using HKDF-SHA256.
 6→ *
 7→ * Derivation path:
 8→ *   secp256k1 privateKey (32 bytes)
 9→ *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-device-registry-ipns-v1")
10→ *     -> 32-byte Ed25519 seed
11→ *     -> Ed25519 keypair
12→ *     -> IPNS name (k51...)
13→ *
14→ * This enables any authenticated session with the user's privateKey
15→ * to discover the registry IPNS name without backend assistance.
16→ */
17→
18→import { deriveKey } from '../keys/derive';
19→import * as ed from '@noble/ed25519';
20→import { deriveIpnsName } from '../ipns/derive-name';
21→import { CryptoError } from '../types';
22→import { SECP256K1_PRIVATE_KEY_SIZE } from '../constants';
23→
24→const REGISTRY_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
25→const REGISTRY_HKDF_INFO = new TextEncoder().encode('cipherbox-device-registry-ipns-v1');
26→
27→/**
28→ * Derive the deterministic Ed25519 IPNS keypair for the device registry.
29→ *
30→ * Given the same secp256k1 privateKey, this always produces the same
31→ * IPNS name, enabling discovery from any device.
32→ *
33→ * @param userPrivateKey - 32-byte secp256k1 private key
34→ * @returns Ed25519 keypair and IPNS name for the registry
35→ * @throws CryptoError if the private key is not 32 bytes
36→ */
37→export async function deriveRegistryIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
38→  privateKey: Uint8Array;
39→  publicKey: Uint8Array;
40→  ipnsName: string;
41→}> {
42→  // Validate input key length
43→  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
44→    throw new CryptoError('Invalid private key size for registry derivation', 'INVALID_KEY_SIZE');
45→  }
46→
47→  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
48→  const ed25519Seed = await deriveKey({
49→    inputKey: userPrivateKey,
50→    salt: REGISTRY_HKDF_SALT,
51→    info: REGISTRY_HKDF_INFO,
52→    outputLength: 32,
53→  });
54→
55→  // 2. Derive Ed25519 public key from seed (deterministic)
56→  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
57→
58→  // 3. Derive IPNS name from Ed25519 public key (k51... format)
59→  const ipnsName = await deriveIpnsName(ed25519PublicKey);
60→
61→  return {
62→    privateKey: ed25519Seed,
63→    publicKey: ed25519PublicKey,
64→    ipnsName,
65→  };
66→}
67→

 1→/**
 2→ * @cipherbox/crypto - Recycle Bin Metadata Types
 3→ *
 4→ * Type definitions for the encrypted recycle bin metadata stored on IPFS/IPNS.
 5→ * The bin tracks soft-deleted files and folders with time-limited retention,
 6→ * enabling recovery to the original vault location.
 7→ */
 8→
 9→import type { FilePointer } from '../file/types';
10→import type { FolderEntry } from '../folder/types';
11→
12→/**
13→ * Individual bin entry representing a soft-deleted item.
14→ *
15→ * Each entry preserves the full FolderChild (FilePointer or FolderEntry)
16→ * that was removed from the parent folder's metadata, enabling restore
17→ * by re-inserting it into the original parent.
18→ */
19→export type BinEntry = {
20→  /** Unique ID for this bin entry (UUID) */
21→  id: string;
22→  /** Original item type */
23→  itemType: 'file' | 'folder';
24→  /** Display name at time of deletion */
25→  name: string;
26→  /** IPNS name of the original parent folder (for restore path resolution) */
27→  originalParentIpnsName: string;
28→  /** Full breadcrumb path at deletion time (e.g., "My Vault / Documents / Reports") */
29→  originalPath: string;
30→  /** When item was deleted (Unix ms) */
31→  deletedAt: number;
32→  /** File/folder size in bytes (0 for folders with unknown size) */
33→  size: number;
34→  /** MIME type (empty string for folders) */
35→  mimeType: string;
36→  /** IPFS CID of the encrypted file content (captured at soft-delete time for unpin on permanent delete) */
37→  contentCid?: string;
38→  /** Original file size in bytes (captured at soft-delete time for quota reclaim on permanent delete) */
39→  contentSize?: number;
40→  /** Version CIDs and sizes (captured at soft-delete time for unpin on permanent delete) */
41→  versionCids?: Array<{ cid: string; size: number }>;
42→
43→  // --- Item reference data (needed for restore and permanent delete) ---
44→
45→  /** For files: the preserved FilePointer from parent folder metadata */
46→  filePointer?: FilePointer;
47→  /** For folders: the preserved FolderEntry from parent folder metadata */
48→  folderEntry?: FolderEntry;
49→};
50→
51→/**
52→ * The full recycle bin metadata.
53→ *
54→ * Encrypted as a single JSON blob with the user's publicKey via ECIES,
55→ * then stored on IPFS and referenced by a dedicated IPNS name.
56→ * Follows the same pattern as DeviceRegistry.
57→ */
58→export type RecycleBinMetadata = {
59→  /** Schema version for future migrations */
60→  version: 'v1';
61→  /** Monotonically increasing update counter */
62→  sequenceNumber: number;
63→  /** Array of all bin entries */
64→  entries: BinEntry[];
65→};
66→

  1→/**
  2→ * @cipherbox/crypto - Recycle Bin Metadata Schema Validation
  3→ *
  4→ * Runtime validation for RecycleBinMetadata JSON after decryption.
  5→ * Uses manual checks consistent with existing codebase patterns
  6→ * (see registry/schema.ts validateDeviceRegistry).
  7→ */
  8→
  9→import { CryptoError } from '../types';
 10→import type { RecycleBinMetadata } from './types';
 11→
 12→const VALID_ITEM_TYPES = ['file', 'folder'];
 13→
 14→/**
 15→ * Validate a parsed JSON object as RecycleBinMetadata.
 16→ *
 17→ * Throws CryptoError with code 'DECRYPTION_FAILED' on validation failure
 18→ * to avoid leaking schema details to attackers.
 19→ *
 20→ * @param data - Unknown parsed JSON data
 21→ * @returns Validated RecycleBinMetadata
 22→ * @throws CryptoError if validation fails
 23→ */
 24→export function validateBinMetadata(data: unknown): RecycleBinMetadata {
 25→  if (typeof data !== 'object' || data === null) {
 26→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
 27→  }
 28→
 29→  const obj = data as Record<string, unknown>;
 30→
 31→  // Validate version
 32→  if (obj.version !== 'v1') {
 33→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
 34→  }
 35→
 36→  // Validate sequenceNumber
 37→  if (
 38→    typeof obj.sequenceNumber !== 'number' ||
 39→    !Number.isInteger(obj.sequenceNumber) ||
 40→    obj.sequenceNumber < 0
 41→  ) {
 42→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
 43→  }
 44→
 45→  // Validate entries array
 46→  if (!Array.isArray(obj.entries)) {
 47→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
 48→  }
 49→
 50→  // Validate each bin entry
 51→  for (const entry of obj.entries) {
 52→    validateBinEntry(entry);
 53→  }
 54→
 55→  return data as RecycleBinMetadata;
 56→}
 57→
 58→/**
 59→ * Validate an individual bin entry.
 60→ */
 61→function validateBinEntry(data: unknown): void {
 62→  if (typeof data !== 'object' || data === null) {
 63→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
 64→  }
 65→
 66→  const entry = data as Record<string, unknown>;
 67→
 68→  // Validate id (non-empty string)
 69→  if (typeof entry.id !== 'string' || entry.id.length === 0) {
 70→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
 71→  }
 72→
 73→  // Validate itemType
 74→  if (typeof entry.itemType !== 'string' || !VALID_ITEM_TYPES.includes(entry.itemType)) {
 75→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
 76→  }
 77→
 78→  // Validate name (string)
 79→  if (typeof entry.name !== 'string') {
 80→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
 81→  }
 82→
 83→  // Validate originalParentIpnsName (string)
 84→  if (typeof entry.originalParentIpnsName !== 'string') {
 85→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
 86→  }
 87→
 88→  // Validate originalPath (string)
 89→  if (typeof entry.originalPath !== 'string') {
 90→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
 91→  }
 92→
 93→  // Validate deletedAt (number)
 94→  if (
 95→    typeof entry.deletedAt !== 'number' ||
 96→    !Number.isFinite(entry.deletedAt) ||
 97→    entry.deletedAt < 0
 98→  ) {
 99→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
100→  }
101→
102→  // Validate size (non-negative finite number)
103→  if (typeof entry.size !== 'number' || !Number.isFinite(entry.size) || entry.size < 0) {
104→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
105→  }
106→
107→  // Validate mimeType (string)
108→  if (typeof entry.mimeType !== 'string') {
109→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
110→  }
111→
112→  // Validate optional contentCid (non-empty string if present)
113→  if (entry.contentCid !== undefined) {
114→    if (typeof entry.contentCid !== 'string' || entry.contentCid.length === 0) {
115→      throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
116→    }
117→  }
118→
119→  // Validate optional contentSize (non-negative finite number if present)
120→  if (entry.contentSize !== undefined) {
121→    if (
122→      typeof entry.contentSize !== 'number' ||
123→      !Number.isFinite(entry.contentSize) ||
124→      entry.contentSize < 0
125→    ) {
126→      throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
127→    }
128→  }
129→
130→  // Validate optional versionCids (array of {cid: string, size: number} if present)
131→  if (entry.versionCids !== undefined) {
132→    if (!Array.isArray(entry.versionCids)) {
133→      throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
134→    }
135→    for (const vc of entry.versionCids) {
136→      if (typeof vc !== 'object' || vc === null) {
137→        throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
138→      }
139→      const v = vc as Record<string, unknown>;
140→      if (typeof v.cid !== 'string' || v.cid.length === 0) {
141→        throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
142→      }
143→      if (typeof v.size !== 'number' || !Number.isFinite(v.size) || v.size < 0) {
144→        throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
145→      }
146→    }
147→  }
148→
149→  // Validate filePointer/folderEntry: optional, but if present must be objects
150→  // Be lenient -- schema may evolve, so we don't enforce strict presence based on itemType
151→  if (
152→    entry.filePointer !== undefined &&
153→    (typeof entry.filePointer !== 'object' || entry.filePointer === null)
154→  ) {
155→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
156→  }
157→
158→  if (
159→    entry.folderEntry !== undefined &&
160→    (typeof entry.folderEntry !== 'object' || entry.folderEntry === null)
161→  ) {
162→    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
163→  }
164→}
165→

 1→/**
 2→ * @cipherbox/crypto - Recycle Bin Metadata Encryption
 3→ *
 4→ * ECIES encryption/decryption for the recycle bin metadata blob.
 5→ * Uses the same wrapKey/unwrapKey primitives as folder key wrapping.
 6→ *
 7→ * Note: wrapKey/unwrapKey handle arbitrary-length data (not just 32-byte keys).
 8→ * eciesjs internally uses AES-256-GCM for the symmetric portion, so any
 9→ * length payload works. Overhead is ~97 bytes (65 ephemeral pubkey + 16 nonce + 16 tag).
10→ */
11→
12→import { wrapKey } from '../ecies/encrypt';
13→import { unwrapKey } from '../ecies/decrypt';
14→import { validateBinMetadata } from './schema';
15→import { CryptoError } from '../types';
16→import { clearBytes } from '../utils/memory';
17→import type { RecycleBinMetadata } from './types';
18→
19→/**
20→ * Encrypt the recycle bin metadata for IPFS storage.
21→ *
22→ * Serializes the metadata to JSON and encrypts with ECIES using
23→ * the user's secp256k1 publicKey. Only the holder of the corresponding
24→ * privateKey can decrypt it.
25→ *
26→ * @param metadata - The recycle bin metadata to encrypt
27→ * @param userPublicKey - 65-byte uncompressed secp256k1 public key
28→ * @returns Encrypted metadata blob
29→ */
30→export async function encryptBinMetadata(
31→  metadata: RecycleBinMetadata,
32→  userPublicKey: Uint8Array
33→): Promise<Uint8Array> {
34→  const plaintext = new TextEncoder().encode(JSON.stringify(metadata));
35→  try {
36→    return await wrapKey(plaintext, userPublicKey);
37→  } finally {
38→    clearBytes(plaintext);
39→  }
40→}
41→
42→/**
43→ * Decrypt the recycle bin metadata from IPFS storage.
44→ *
45→ * Decrypts with ECIES using the user's secp256k1 privateKey,
46→ * parses the JSON, and validates the schema.
47→ *
48→ * @param encrypted - ECIES-encrypted metadata blob from IPFS
49→ * @param userPrivateKey - 32-byte secp256k1 private key
50→ * @returns Validated RecycleBinMetadata
51→ * @throws CryptoError if decryption or validation fails
52→ */
53→export async function decryptBinMetadata(
54→  encrypted: Uint8Array,
55→  userPrivateKey: Uint8Array
56→): Promise<RecycleBinMetadata> {
57→  const plaintext = await unwrapKey(encrypted, userPrivateKey);
58→  try {
59→    const json = new TextDecoder().decode(plaintext);
60→    const parsed = JSON.parse(json);
61→    return validateBinMetadata(parsed);
62→  } catch (error) {
63→    if (error instanceof CryptoError) throw error;
64→    throw new CryptoError('Bin metadata decryption produced invalid data', 'DECRYPTION_FAILED');
65→  } finally {
66→    clearBytes(plaintext);
67→  }
68→}
69→

 1→/**
 2→ * @cipherbox/crypto - Recycle Bin IPNS Key Derivation
 3→ *
 4→ * Derives a deterministic Ed25519 IPNS keypair for the recycle bin
 5→ * from the user's secp256k1 privateKey using HKDF-SHA256.
 6→ *
 7→ * Derivation path:
 8→ *   secp256k1 privateKey (32 bytes)
 9→ *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-recycle-bin-ipns-v1")
10→ *     -> 32-byte Ed25519 seed
11→ *     -> Ed25519 keypair
12→ *     -> IPNS name (k51...)
13→ *
14→ * This enables any authenticated session with the user's privateKey
15→ * to discover the recycle bin IPNS name without backend assistance.
16→ */
17→
18→import { deriveKey } from '../keys/derive';
19→import * as ed from '@noble/ed25519';
20→import { deriveIpnsName } from '../ipns/derive-name';
21→import { CryptoError } from '../types';
22→import { SECP256K1_PRIVATE_KEY_SIZE } from '../constants';
23→
24→const BIN_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
25→const BIN_HKDF_INFO = new TextEncoder().encode('cipherbox-recycle-bin-ipns-v1');
26→
27→/**
28→ * Derive the deterministic Ed25519 IPNS keypair for the recycle bin.
29→ *
30→ * Given the same secp256k1 privateKey, this always produces the same
31→ * IPNS name, enabling discovery from any device.
32→ *
33→ * @param userPrivateKey - 32-byte secp256k1 private key
34→ * @returns Ed25519 keypair and IPNS name for the recycle bin
35→ * @throws CryptoError if the private key is not 32 bytes
36→ */
37→export async function deriveBinIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
38→  privateKey: Uint8Array;
39→  publicKey: Uint8Array;
40→  ipnsName: string;
41→}> {
42→  // Validate input key length
43→  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
44→    throw new CryptoError('Invalid private key size for bin derivation', 'INVALID_KEY_SIZE');
45→  }
46→
47→  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
48→  const ed25519Seed = await deriveKey({
49→    inputKey: userPrivateKey,
50→    salt: BIN_HKDF_SALT,
51→    info: BIN_HKDF_INFO,
52→    outputLength: 32,
53→  });
54→
55→  // 2. Derive Ed25519 public key from seed (deterministic)
56→  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
57→
58→  // 3. Derive IPNS name from Ed25519 public key (k51... format)
59→  const ipnsName = await deriveIpnsName(ed25519PublicKey);
60→
61→  return {
62→    privateKey: ed25519Seed,
63→    publicKey: ed25519PublicKey,
64→    ipnsName,
65→  };
66→}
67→

 1→/**
 2→ * @cipherbox/crypto - IPNS Record Creation
 3→ *
 4→ * Creates IPNS records using the ipns npm package.
 5→ * Handles conversion from @noble/ed25519 raw keys to libp2p format.
 6→ */
 7→
 8→import { createIPNSRecord as ipnsCreate, type IPNSRecord } from 'ipns';
 9→import { privateKeyFromRaw } from '@libp2p/crypto/keys';
10→import * as ed from '@noble/ed25519';
11→import { CryptoError } from '../types';
12→
13→/** Default IPNS record lifetime: 24 hours in milliseconds */
14→const DEFAULT_LIFETIME_MS = 24 * 60 * 60 * 1000;
15→
16→/**
17→ * Creates an IPNS record signed with the given Ed25519 private key.
18→ *
19→ * The ipns package handles:
20→ * - CBOR encoding of record data
21→ * - V1 and V2 signature creation
22→ * - Proper validity timestamp formatting
23→ *
24→ * @param ed25519PrivateKey - 32-byte Ed25519 private key (seed) from @noble/ed25519
25→ * @param value - IPFS path to point to (e.g., "/ipfs/bafy...")
26→ * @param sequenceNumber - Monotonically increasing sequence number
27→ * @param lifetimeMs - Record validity lifetime in milliseconds (default: 24 hours)
28→ * @returns IPNS record ready for marshaling and publishing
29→ * @throws CryptoError if key conversion or record creation fails
30→ */
31→export async function createIpnsRecord(
32→  ed25519PrivateKey: Uint8Array,
33→  value: string,
34→  sequenceNumber: bigint,
35→  lifetimeMs: number = DEFAULT_LIFETIME_MS
36→): Promise<IPNSRecord> {
37→  // Validate private key size
38→  if (ed25519PrivateKey.length !== 32) {
39→    throw new CryptoError('Invalid Ed25519 private key size', 'INVALID_PRIVATE_KEY_SIZE');
40→  }
41→
42→  // [SECURITY: MEDIUM-06] Validate sequence number is non-negative
43→  if (sequenceNumber < 0n) {
44→    throw new CryptoError('Sequence number must be non-negative', 'SIGNING_FAILED');
45→  }
46→
47→  // Intermediate key material buffer - we'll zero this after use
48→  let libp2pKeyBytes: Uint8Array | null = null;
49→
50→  try {
51→    // Convert 32-byte @noble/ed25519 private key to libp2p format:
52→    // libp2p expects 64 bytes: [privateKey (32) + publicKey (32)]
53→    const publicKey = ed.getPublicKey(ed25519PrivateKey);
54→    libp2pKeyBytes = new Uint8Array(64);
55→    libp2pKeyBytes.set(ed25519PrivateKey, 0);
56→    libp2pKeyBytes.set(publicKey, 32);
57→
58→    // Convert to libp2p PrivateKey object
59→    const libp2pPrivateKey = privateKeyFromRaw(libp2pKeyBytes);
60→
61→    // [SECURITY: MEDIUM-05] Clear intermediate key material immediately after conversion
62→    libp2pKeyBytes.fill(0);
63→    libp2pKeyBytes = null;
64→
65→    // Create IPNS record using the ipns package
66→    // v1Compatible: true creates both V1 and V2 signatures for maximum compatibility
67→    const record = await ipnsCreate(libp2pPrivateKey, value, sequenceNumber, lifetimeMs, {
68→      v1Compatible: true,
69→    });
70→
71→    return record;
72→  } catch (error) {
73→    // [SECURITY: MEDIUM-05] Ensure key material is cleared even on error
74→    if (libp2pKeyBytes) {
75→      libp2pKeyBytes.fill(0);
76→    }
77→
78→    // Re-throw CryptoErrors as-is
79→    if (error instanceof CryptoError) {
80→      throw error;
81→    }
82→    // Wrap other errors
83→    throw new CryptoError('IPNS record creation failed', 'SIGNING_FAILED');
84→  }
85→}
86→
87→// Re-export the IPNSRecord type for consumers
88→export type { IPNSRecord };
89→

 1→/**
 2→ * @cipherbox/crypto - IPNS Name Derivation
 3→ *
 4→ * Derives IPNS name (CIDv1 with libp2p-key codec) from Ed25519 public key.
 5→ */
 6→
 7→import { publicKeyFromRaw } from '@libp2p/crypto/keys';
 8→import { peerIdFromPublicKey } from '@libp2p/peer-id';
 9→import { base36 } from 'multiformats/bases/base36';
10→import { CryptoError } from '../types';
11→import { ED25519_PUBLIC_KEY_SIZE } from '../constants';
12→
13→/**
14→ * Derives the IPNS name from an Ed25519 public key.
15→ *
16→ * The IPNS name is a CIDv1 with:
17→ * - libp2p-key multicodec (0x72)
18→ * - identity multihash containing the protobuf-encoded public key
19→ *
20→ * This produces names starting with "k51..." in base36 encoding.
21→ *
22→ * @param ed25519PublicKey - 32-byte Ed25519 public key
23→ * @returns IPNS name string (e.g., "k51qzi5uqu5...")
24→ * @throws CryptoError if public key is invalid
25→ */
26→export async function deriveIpnsName(ed25519PublicKey: Uint8Array): Promise<string> {
27→  // Validate public key size
28→  if (ed25519PublicKey.length !== ED25519_PUBLIC_KEY_SIZE) {
29→    throw new CryptoError('Invalid Ed25519 public key size', 'INVALID_PUBLIC_KEY_SIZE');
30→  }
31→
32→  try {
33→    // Convert raw 32-byte public key to libp2p PublicKey object
34→    const libp2pPublicKey = publicKeyFromRaw(ed25519PublicKey);
35→
36→    // Create PeerId from the public key
37→    const peerId = peerIdFromPublicKey(libp2pPublicKey);
38→
39→    // Return CIDv1 string representation in base36 (k51... format)
40→    return peerId.toCID().toString(base36);
41→  } catch (error) {
42→    // Re-throw CryptoErrors as-is
43→    if (error instanceof CryptoError) {
44→      throw error;
45→    }
46→    // Wrap other errors
47→    throw new CryptoError('IPNS name derivation failed', 'SIGNING_FAILED');
48→  }
49→}
50→

