/**
 * @cipherbox/core - Folder Metadata Types
 *
 * Type definitions for encrypted folder metadata stored in IPNS records.
 * v2 schema with per-file IPNS pointers (FilePointer children).
 */

import type { FilePointer } from '../file/types';

/**
 * Decrypted folder metadata structure (v2).
 * The entire FolderMetadata object is encrypted as a single blob with AES-256-GCM.
 * Children are FolderEntry (subfolders) or FilePointer (slim IPNS references).
 */
export type FolderMetadata = {
  /** Schema version */
  version: 'v2';
  /** Folders and file pointers in this folder */
  children: FolderChild[];
};

/**
 * A child entry can be either a folder or a file pointer.
 */
export type FolderChild = FolderEntry | FilePointer;

/**
 * Subfolder entry within folder metadata.
 * Contains ECIES-wrapped keys for accessing the subfolder.
 */
export type FolderEntry = {
  type: 'folder';
  /** UUID for internal reference */
  id: string;
  /** Folder name (plaintext, since whole metadata is encrypted) */
  name: string;
  /** IPNS name for this subfolder (k51... format) */
  ipnsName: string;
  /** Hex-encoded ECIES-wrapped Ed25519 private key for IPNS signing */
  ipnsPrivateKeyEncrypted: string;
  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting subfolder metadata */
  folderKeyEncrypted: string;
  /** Creation timestamp (Unix ms) */
  createdAt: number;
  /** Last modification timestamp (Unix ms) */
  modifiedAt: number;
};

/**
 * Encrypted folder metadata for storage/transmission.
 * This is what gets uploaded to IPFS and referenced by IPNS.
 */
export type EncryptedFolderMetadata = {
  /** Hex-encoded 12-byte IV for AES-GCM */
  iv: string;
  /** Base64-encoded AES-GCM ciphertext (includes 16-byte auth tag) */
  data: string;
};

import axios, { type AxiosInstance, type AxiosProgressEvent, type CancelToken } from 'axios';

export type ApiClientConfig = {
  /** Base URL for the CipherBox API (e.g., "http://localhost:3000") */
  baseUrl: string;
  /** Returns a valid access token. Consumer owns refresh logic. */
  getAccessToken: () => Promise<string>;
};

/**
 * Create a configured axios instance for CipherBox API calls.
 * No Zustand, no import.meta.env -- all config injected by consumer.
 */
export function createAxiosInstance(config: ApiClientConfig): AxiosInstance {
  const instance = axios.create({ baseURL: config.baseUrl });
  instance.interceptors.request.use(async (reqConfig) => {
    const token = await config.getAccessToken();
    if (token) {
      reqConfig.headers.Authorization = `Bearer ${token}`;
    }
    return reqConfig;
  });
  return instance;
}

/**
 * Custom instance function for orval-generated code.
 * Matches the signature orval expects from a mutator.
 * The consumer must call setApiClientConfig() before using generated functions.
 */
let _config: ApiClientConfig | null = null;

export function setApiClientConfig(config: ApiClientConfig): void {
  _config = config;
}

export function getApiClientConfig(): ApiClientConfig {
  if (!_config) throw new Error('API client not configured. Call setApiClientConfig() first.');
  return _config;
}

export const customInstance = async <T>(requestConfig: {
  url: string;
  method: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
  params?: Record<string, string | number | boolean | undefined>;
  data?: unknown;
  headers?: Record<string, string>;
  signal?: AbortSignal;
  responseType?: 'json' | 'blob' | 'text';
}): Promise<T> => {
  const config = getApiClientConfig();
  const { url, method, params, data, headers, signal, responseType = 'json' } = requestConfig;
  const token = await config.getAccessToken();

  const queryString = params
    ? '?' + new URLSearchParams(
        Object.entries(params)
          .filter(([, v]) => v !== undefined)
          .map(([k, v]) => [k, String(v)])
      ).toString()
    : '';

  const response = await fetch(`${config.baseUrl}${url}${queryString}`, {
    method,
    headers: {
      ...(data && responseType === 'json' ? { 'Content-Type': 'application/json' } : {}),
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...headers,
    },
    body: data ? JSON.stringify(data) : undefined,
    signal,
  });

  if (!response.ok) {
    const err = new Error(`HTTP error! status: ${response.status}`);
    (err as Error & { status: number }).status = response.status;
    throw err;
  }

  if (responseType === 'blob') return response.blob() as Promise<T>;
  if (responseType === 'text') return response.text() as Promise<T>;
  // Responses with no body (204 No Content, 201 with void return, etc.)
  const text = await response.text();
  if (!text.trim()) return undefined as T;
  return JSON.parse(text);
};

export default customInstance;

