/**
 * @cipherbox/core - Device Registry Encryption
 *
 * ECIES encryption/decryption for the device registry blob.
 * Uses the same wrapKey/unwrapKey primitives as folder key wrapping.
 *
 * Note: wrapKey/unwrapKey handle arbitrary-length data (not just 32-byte keys).
 * eciesjs internally uses AES-256-GCM for the symmetric portion, so any
 * length payload works. Overhead is ~97 bytes (65 ephemeral pubkey + 16 nonce + 16 tag).
 * A 10KB registry produces ~10.1KB ciphertext.
 */

import { wrapKey, unwrapKey, CryptoError, clearBytes } from '@cipherbox/crypto';
import { validateDeviceRegistry } from './schema';
import type { DeviceRegistry } from './types';

/**
 * Encrypt the device registry for IPFS storage.
 *
 * Serializes the registry to JSON and encrypts with ECIES using
 * the user's secp256k1 publicKey. Only the holder of the corresponding
 * privateKey can decrypt it.
 *
 * @param registry - The device registry to encrypt
 * @param userPublicKey - 65-byte uncompressed secp256k1 public key
 * @returns Encrypted registry blob
 */
export async function encryptRegistry(
  registry: DeviceRegistry,
  userPublicKey: Uint8Array
): Promise<Uint8Array> {
  const plaintext = new TextEncoder().encode(JSON.stringify(registry));
  try {
    return await wrapKey(plaintext, userPublicKey);
  } finally {
    clearBytes(plaintext);
  }
}

/**
 * Decrypt the device registry from IPFS storage.
 *
 * Decrypts with ECIES using the user's secp256k1 privateKey,
 * parses the JSON, and validates the schema.
 *
 * @param encrypted - ECIES-encrypted registry blob from IPFS
 * @param userPrivateKey - 32-byte secp256k1 private key
 * @returns Validated DeviceRegistry
 * @throws CryptoError if decryption or validation fails
 */
export async function decryptRegistry(
  encrypted: Uint8Array,
  userPrivateKey: Uint8Array
): Promise<DeviceRegistry> {
  const plaintext = await unwrapKey(encrypted, userPrivateKey);
  try {
    const json = new TextDecoder().decode(plaintext);
    const parsed = JSON.parse(json);
    return validateDeviceRegistry(parsed);
  } catch (error) {
    if (error instanceof CryptoError) throw error;
    throw new CryptoError('Registry decryption produced invalid data', 'DECRYPTION_FAILED');
  } finally {
    clearBytes(plaintext);
  }
}

/**
 * @cipherbox/core - Registry IPNS Key Derivation
 *
 * Derives a deterministic Ed25519 IPNS keypair for the device registry
 * from the user's secp256k1 privateKey using HKDF-SHA256.
 *
 * Derivation path:
 *   secp256k1 privateKey (32 bytes)
 *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-device-registry-ipns-v1")
 *     -> 32-byte Ed25519 seed
 *     -> Ed25519 keypair
 *     -> IPNS name (k51...)
 *
 * This enables any authenticated session with the user's privateKey
 * to discover the registry IPNS name without backend assistance.
 */

import { deriveKey, CryptoError, SECP256K1_PRIVATE_KEY_SIZE } from '@cipherbox/crypto';
import * as ed from '@noble/ed25519';
import { deriveIpnsName } from '../ipns/derive-name';

const REGISTRY_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
const REGISTRY_HKDF_INFO = new TextEncoder().encode('cipherbox-device-registry-ipns-v1');

/**
 * Derive the deterministic Ed25519 IPNS keypair for the device registry.
 *
 * Given the same secp256k1 privateKey, this always produces the same
 * IPNS name, enabling discovery from any device.
 *
 * @param userPrivateKey - 32-byte secp256k1 private key
 * @returns Ed25519 keypair and IPNS name for the registry
 * @throws CryptoError if the private key is not 32 bytes
 */
export async function deriveRegistryIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
  privateKey: Uint8Array;
  publicKey: Uint8Array;
  ipnsName: string;
}> {
  // Validate input key length
  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
    throw new CryptoError('Invalid private key size for registry derivation', 'INVALID_KEY_SIZE');
  }

  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
  const ed25519Seed = await deriveKey({
    inputKey: userPrivateKey,
    salt: REGISTRY_HKDF_SALT,
    info: REGISTRY_HKDF_INFO,
    outputLength: 32,
  });

  // 2. Derive Ed25519 public key from seed (deterministic)
  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);

  // 3. Derive IPNS name from Ed25519 public key (k51... format)
  const ipnsName = await deriveIpnsName(ed25519PublicKey);

  return {
    privateKey: ed25519Seed,
    publicKey: ed25519PublicKey,
    ipnsName,
  };
}

/**
 * @cipherbox/core - Device Registry Module
 *
 * Crypto primitives for the encrypted device registry:
 * - Types for registry schema
 * - Runtime validation
 * - ECIES encryption/decryption
 * - Deterministic IPNS keypair derivation
 */

export type { DeviceAuthStatus, DevicePlatform, DeviceEntry, DeviceRegistry } from './types';

export { validateDeviceRegistry } from './schema';
export { encryptRegistry, decryptRegistry } from './encrypt';
export { deriveRegistryIpnsKeypair } from './derive-ipns';

/**
 * @cipherbox/core - Recycle Bin Metadata Types
 *
 * Type definitions for the encrypted recycle bin metadata stored on IPFS/IPNS.
 * The bin tracks soft-deleted files and folders with time-limited retention,
 * enabling recovery to the original vault location.
 */

import type { FilePointer } from '../file/types';
import type { FolderEntry } from '../folder/types';

/**
 * Individual bin entry representing a soft-deleted item.
 *
 * Each entry preserves the full FolderChild (FilePointer or FolderEntry)
 * that was removed from the parent folder's metadata, enabling restore
 * by re-inserting it into the original parent.
 */
export type BinEntry = {
  /** Unique ID for this bin entry (UUID) */
  id: string;
  /** Original item type */
  itemType: 'file' | 'folder';
  /** Display name at time of deletion */
  name: string;
  /** IPNS name of the original parent folder (for restore path resolution) */
  originalParentIpnsName: string;
  /** Full breadcrumb path at deletion time (e.g., "My Vault / Documents / Reports") */
  originalPath: string;
  /** When item was deleted (Unix ms) */
  deletedAt: number;
  /** File/folder size in bytes (0 for folders with unknown size) */
  size: number;
  /** MIME type (empty string for folders) */
  mimeType: string;
  /** IPFS CID of the encrypted file content (captured at soft-delete time for unpin on permanent delete) */
  contentCid?: string;
  /** Original file size in bytes (captured at soft-delete time for quota reclaim on permanent delete) */
  contentSize?: number;
  /** Version CIDs and sizes (captured at soft-delete time for unpin on permanent delete) */
  versionCids?: Array<{ cid: string; size: number }>;

  // --- Item reference data (needed for restore and permanent delete) ---

  /** For files: the preserved FilePointer from parent folder metadata */
  filePointer?: FilePointer;
  /** For folders: the preserved FolderEntry from parent folder metadata */
  folderEntry?: FolderEntry;
};

/**
 * The full recycle bin metadata.
 *
 * Encrypted as a single JSON blob with the user's publicKey via ECIES,
 * then stored on IPFS and referenced by a dedicated IPNS name.
 * Follows the same pattern as DeviceRegistry.
 */
export type RecycleBinMetadata = {
  /** Schema version for future migrations */
  version: 'v1';
  /** Monotonically increasing update counter */
  sequenceNumber: number;
  /** Array of all bin entries */
  entries: BinEntry[];
};

/**
 * @cipherbox/core - Recycle Bin Metadata Schema Validation
 *
 * Runtime validation for RecycleBinMetadata JSON after decryption.
 * Uses manual checks consistent with existing codebase patterns
 * (see registry/schema.ts validateDeviceRegistry).
 */

import { CryptoError } from '@cipherbox/crypto';
import type { RecycleBinMetadata } from './types';

const VALID_ITEM_TYPES = ['file', 'folder'];

/**
 * Validate a parsed JSON object as RecycleBinMetadata.
 *
 * Throws CryptoError with code 'DECRYPTION_FAILED' on validation failure
 * to avoid leaking schema details to attackers.
 *
 * @param data - Unknown parsed JSON data
 * @returns Validated RecycleBinMetadata
 * @throws CryptoError if validation fails
 */
export function validateBinMetadata(data: unknown): RecycleBinMetadata {
  if (typeof data !== 'object' || data === null) {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  const obj = data as Record<string, unknown>;

  // Validate version
  if (obj.version !== 'v1') {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  // Validate sequenceNumber
  if (
    typeof obj.sequenceNumber !== 'number' ||
    !Number.isInteger(obj.sequenceNumber) ||
    obj.sequenceNumber < 0
  ) {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  // Validate entries array
  if (!Array.isArray(obj.entries)) {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  // Validate each bin entry
  for (const entry of obj.entries) {
    validateBinEntry(entry);
  }

  return data as RecycleBinMetadata;
}

/**
 * Validate an individual bin entry.
 */
function validateBinEntry(data: unknown): void {
  if (typeof data !== 'object' || data === null) {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  const entry = data as Record<string, unknown>;

  // Validate id (non-empty string)
  if (typeof entry.id !== 'string' || entry.id.length === 0) {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  // Validate itemType
  if (typeof entry.itemType !== 'string' || !VALID_ITEM_TYPES.includes(entry.itemType)) {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  // Validate name (string)
  if (typeof entry.name !== 'string') {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  // Validate originalParentIpnsName (string)
  if (typeof entry.originalParentIpnsName !== 'string') {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  // Validate originalPath (string)
  if (typeof entry.originalPath !== 'string') {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  // Validate deletedAt (number)
  if (
    typeof entry.deletedAt !== 'number' ||
    !Number.isFinite(entry.deletedAt) ||
    entry.deletedAt < 0
  ) {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  // Validate size (non-negative finite number)
  if (typeof entry.size !== 'number' || !Number.isFinite(entry.size) || entry.size < 0) {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  // Validate mimeType (string)
  if (typeof entry.mimeType !== 'string') {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  // Validate optional contentCid (non-empty string if present)
  if (entry.contentCid !== undefined) {
    if (typeof entry.contentCid !== 'string' || entry.contentCid.length === 0) {
      throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
    }
  }

  // Validate optional contentSize (non-negative finite number if present)
  if (entry.contentSize !== undefined) {
    if (
      typeof entry.contentSize !== 'number' ||
      !Number.isFinite(entry.contentSize) ||
      entry.contentSize < 0
    ) {
      throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
    }
  }

  // Validate optional versionCids (array of {cid: string, size: number} if present)
  if (entry.versionCids !== undefined) {
    if (!Array.isArray(entry.versionCids)) {
      throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
    }
    for (const vc of entry.versionCids) {
      if (typeof vc !== 'object' || vc === null) {
        throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
      }
      const v = vc as Record<string, unknown>;
      if (typeof v.cid !== 'string' || v.cid.length === 0) {
        throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
      }
      if (typeof v.size !== 'number' || !Number.isFinite(v.size) || v.size < 0) {
        throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
      }
    }
  }

  // Validate filePointer/folderEntry: optional, but if present must be objects
  // Be lenient -- schema may evolve, so we don't enforce strict presence based on itemType
  if (
    entry.filePointer !== undefined &&
    (typeof entry.filePointer !== 'object' || entry.filePointer === null)
  ) {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }

  if (
    entry.folderEntry !== undefined &&
    (typeof entry.folderEntry !== 'object' || entry.folderEntry === null)
  ) {
    throw new CryptoError('Invalid bin metadata format', 'DECRYPTION_FAILED');
  }
}

/**
 * @cipherbox/core - Recycle Bin Metadata Encryption
 *
 * ECIES encryption/decryption for the recycle bin metadata blob.
 * Uses the same wrapKey/unwrapKey primitives as folder key wrapping.
 *
 * Note: wrapKey/unwrapKey handle arbitrary-length data (not just 32-byte keys).
 * eciesjs internally uses AES-256-GCM for the symmetric portion, so any
 * length payload works. Overhead is ~97 bytes (65 ephemeral pubkey + 16 nonce + 16 tag).
 */

import { wrapKey, unwrapKey, CryptoError, clearBytes } from '@cipherbox/crypto';
import { validateBinMetadata } from './schema';
import type { RecycleBinMetadata } from './types';

/**
 * Encrypt the recycle bin metadata for IPFS storage.
 *
 * Serializes the metadata to JSON and encrypts with ECIES using
 * the user's secp256k1 publicKey. Only the holder of the corresponding
 * privateKey can decrypt it.
 *
 * @param metadata - The recycle bin metadata to encrypt
 * @param userPublicKey - 65-byte uncompressed secp256k1 public key
 * @returns Encrypted metadata blob
 */
export async function encryptBinMetadata(
  metadata: RecycleBinMetadata,
  userPublicKey: Uint8Array
): Promise<Uint8Array> {
  const plaintext = new TextEncoder().encode(JSON.stringify(metadata));
  try {
    return await wrapKey(plaintext, userPublicKey);
  } finally {
    clearBytes(plaintext);
  }
}

/**
 * Decrypt the recycle bin metadata from IPFS storage.
 *
 * Decrypts with ECIES using the user's secp256k1 privateKey,
 * parses the JSON, and validates the schema.
 *
 * @param encrypted - ECIES-encrypted metadata blob from IPFS
 * @param userPrivateKey - 32-byte secp256k1 private key
 * @returns Validated RecycleBinMetadata
 * @throws CryptoError if decryption or validation fails
 */
export async function decryptBinMetadata(
  encrypted: Uint8Array,
  userPrivateKey: Uint8Array
): Promise<RecycleBinMetadata> {
  const plaintext = await unwrapKey(encrypted, userPrivateKey);
  try {
    const json = new TextDecoder().decode(plaintext);
    const parsed = JSON.parse(json);
    return validateBinMetadata(parsed);
  } catch (error) {
    if (error instanceof CryptoError) throw error;
    throw new CryptoError('Bin metadata decryption produced invalid data', 'DECRYPTION_FAILED');
  } finally {
    clearBytes(plaintext);
  }
}

/**
 * @cipherbox/core - Recycle Bin IPNS Key Derivation
 *
 * Derives a deterministic Ed25519 IPNS keypair for the recycle bin
 * from the user's secp256k1 privateKey using HKDF-SHA256.
 *
 * Derivation path:
 *   secp256k1 privateKey (32 bytes)
 *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-recycle-bin-ipns-v1")
 *     -> 32-byte Ed25519 seed
 *     -> Ed25519 keypair
 *     -> IPNS name (k51...)
 *
 * This enables any authenticated session with the user's privateKey
 * to discover the recycle bin IPNS name without backend assistance.
 */

import { deriveKey, CryptoError, SECP256K1_PRIVATE_KEY_SIZE } from '@cipherbox/crypto';
import * as ed from '@noble/ed25519';
import { deriveIpnsName } from '../ipns/derive-name';

const BIN_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
const BIN_HKDF_INFO = new TextEncoder().encode('cipherbox-recycle-bin-ipns-v1');

/**
 * Derive the deterministic Ed25519 IPNS keypair for the recycle bin.
 *
 * Given the same secp256k1 privateKey, this always produces the same
 * IPNS name, enabling discovery from any device.
 *
 * @param userPrivateKey - 32-byte secp256k1 private key
 * @returns Ed25519 keypair and IPNS name for the recycle bin
 * @throws CryptoError if the private key is not 32 bytes
 */
export async function deriveBinIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
  privateKey: Uint8Array;
  publicKey: Uint8Array;
  ipnsName: string;
}> {
  // Validate input key length
  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
    throw new CryptoError('Invalid private key size for bin derivation', 'INVALID_KEY_SIZE');
  }

  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
  const ed25519Seed = await deriveKey({
    inputKey: userPrivateKey,
    salt: BIN_HKDF_SALT,
    info: BIN_HKDF_INFO,
    outputLength: 32,
  });

  // 2. Derive Ed25519 public key from seed (deterministic)
  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);

  // 3. Derive IPNS name from Ed25519 public key (k51... format)
  const ipnsName = await deriveIpnsName(ed25519PublicKey);

  return {
    privateKey: ed25519Seed,
    publicKey: ed25519PublicKey,
    ipnsName,
  };
}

