 * Derives IPNS name (CIDv1 with libp2p-key codec) from Ed25519 public key.
 *
 * NOTE: This file is kept in @cipherbox/crypto because vault/derive-ipns.ts
 * (which stays in crypto) depends on it. The full IPNS module lives in
 * @cipherbox/core, which also has its own copy of this function.
 */

import { publicKeyFromRaw } from '@libp2p/crypto/keys';
import { peerIdFromPublicKey } from '@libp2p/peer-id';
import { base36 } from 'multiformats/bases/base36';
import { CryptoError } from '../types';
import { ED25519_PUBLIC_KEY_SIZE } from '../constants';

/**
 * Derives the IPNS name from an Ed25519 public key.
 *
 * The IPNS name is a CIDv1 with:
 * - libp2p-key multicodec (0x72)
 * - identity multihash containing the protobuf-encoded public key
 *
 * This produces names starting with "k51..." in base36 encoding.
 *
 * @param ed25519PublicKey - 32-byte Ed25519 public key
 * @returns IPNS name string (e.g., "k51qzi5uqu5...")
 * @throws CryptoError if public key is invalid
 */
export async function deriveIpnsName(ed25519PublicKey: Uint8Array): Promise<string> {
  // Validate public key size
  if (ed25519PublicKey.length !== ED25519_PUBLIC_KEY_SIZE) {
    throw new CryptoError('Invalid Ed25519 public key size', 'INVALID_PUBLIC_KEY_SIZE');
  }

  try {
    // Convert raw 32-byte public key to libp2p PublicKey object
    const libp2pPublicKey = publicKeyFromRaw(ed25519PublicKey);

    // Create PeerId from the public key
    const peerId = peerIdFromPublicKey(libp2pPublicKey);

    // Return CIDv1 string representation in base36 (k51... format)
    return peerId.toCID().toString(base36);
  } catch (error) {
    // Re-throw CryptoErrors as-is
    if (error instanceof CryptoError) {
      throw error;
    }
    // Wrap other errors
    throw new CryptoError('IPNS name derivation failed', 'SIGNING_FAILED');
  }
}

/**
 * @cipherbox/crypto
 *
 * Shared cryptographic utilities for CipherBox.
 * Provides AES-256-GCM encryption, ECIES key wrapping, Ed25519 signing,
 * key derivation, and IPNS name derivation.
 *
 * Security principles:
 * - All operations use Web Crypto API or audited libraries (@noble/*, eciesjs)
 * - Error messages are generic to prevent oracle attacks
 * - Keys are Uint8Array - never convert to/from strings for sensitive data
 * - Private keys exist in memory only - never persisted to storage
 *
 * NOTE: Domain-specific modules (folder, file, registry, bin, vault/init, ipns)
 * have moved to @cipherbox/core. This package retains only pure crypto primitives
 * and key derivation functions.
 */

export const CRYPTO_VERSION = '0.2.0';

// Vault IPNS key derivation (only derivation stays in crypto)
export { deriveVaultIpnsKeypair } from './vault';

// Key hierarchy and derivation
export { deriveKey, deriveContextKey, generateFolderKey, type DeriveKeyParams } from './keys';

// AES-256-GCM symmetric encryption
export { encryptAesGcm, decryptAesGcm, sealAesGcm, unsealAesGcm } from './aes';

// AES-256-CTR streaming encryption (random-access decryption for media)
export { encryptAesCtr, decryptAesCtr, decryptAesCtrRange } from './aes';

// ECIES secp256k1 key wrapping
export { wrapKey, unwrapKey, reWrapKey } from './ecies';

// Ed25519 signing for IPNS
export { generateEd25519Keypair, type Ed25519Keypair } from './ed25519';
export { signEd25519, verifyEd25519 } from './ed25519/sign';

// IPNS name derivation (kept in crypto for vault/derive-ipns.ts dependency)
export { deriveIpnsName } from './ipns/derive-name';

// Device identity (per-device Ed25519 keypair)
export { generateDeviceKeypair, deriveDeviceId, type DeviceKeypair } from './device';

// Utility functions (only safe public utilities)
export {
  hexToBytes,
  bytesToHex,
  concatBytes,
  clearBytes,
  clearAll,
  generateRandomBytes,
  generateFileKey,
  generateIv,
  generateCtrIv,
} from './utils';

// Types
export { CryptoError, type CryptoErrorCode, type VaultKey, type EncryptedData } from './types';

// Constants
export {
  AES_KEY_SIZE,
  AES_IV_SIZE,
  AES_TAG_SIZE,
  SECP256K1_PUBLIC_KEY_SIZE,
  SECP256K1_PRIVATE_KEY_SIZE,
  ECIES_MIN_CIPHERTEXT_SIZE,
  AES_GCM_ALGORITHM,
  AES_CTR_IV_SIZE,
  AES_CTR_NONCE_SIZE,
  AES_CTR_LENGTH,
  AES_CTR_ALGORITHM,
  ED25519_PUBLIC_KEY_SIZE,
  ED25519_PRIVATE_KEY_SIZE,
  ED25519_SIGNATURE_SIZE,
} from './constants';

